"""Core vector operations."""


def dotproduct(a, b):
    """Return the dot product of two equal-length sequences of numbers.

    a, b: iterables of ints or floats.
    """
    if len(a) != len(b):
        raise ValueError("sequences must have the same length")
    return sum(x * y for x, y in zip(a, b))

from vectorops import dotproduct


def test_dotproduct_basic():
    assert 1 == dotproduct([1, 1], [0, 1])


def test_dotproduct_value():
    assert dotproduct([1, 2, 3], [4, 5, 6]) == 32
